def retrieve(question: str, user: Principal) -> list[Chunk]:
    # Filter is built from the verified JWT, never from request parameters.
    flt = {"andAll": [
        {"in": {"key": "matter_id", "value": user.matter_ids}},
        {"in": {"key": "security_group", "value": user.groups}},
    ]}
    if not user.may_see_privileged:
        flt["andAll"].append({"equals": {"key": "privileged", "value": False}})
    resp = agent_rt.retrieve(
        knowledgeBaseId=KB_ID,
        retrievalQuery={"text": question},
        retrievalConfiguration={"vectorSearchConfiguration": {
            "numberOfResults": 8, "filter": flt}},
    )
    chunks = [Chunk.from_result(r) for r in resp["retrievalResults"]]
    # Defence in depth: re-check every document id against authz.
    leaked = [c for c in chunks if not authz.can_read(user, c.document_id)]
    if leaked:
        audit.alert("retrieval_boundary_violation", user.id,
                    [c.document_id for c in leaked])
        raise PermissionError("retrieval returned unauthorized documents")
    return chunks

# USD per 1M tokens; keep in config, prices change.
PRICE = {"eu.anthropic.claude-sonnet-4-5-20250929-v1:0": (3.00, 15.00)}

def record_cost(model_id: str, usage: dict, dims: dict) -> float:
    in_p, out_p = PRICE[model_id]
    cost = (usage["inputTokens"] / 1e6) * in_p + (usage["outputTokens"] / 1e6) * out_p
    cw.put_metric_data(
        Namespace="Agent/Cost",
        MetricData=[{
            "MetricName": "RequestCostUSD",
            # dims: matterId, step (plan|retrieve|tool|answer), modelId
            "Dimensions": [{"Name": k, "Value": v} for k, v in dims.items()],
            "Value": cost,
            "Unit": "None",
        }],
    )
    return cost
